const LAB=[
{pre:"白鷺",post:"川の向こうへ渡りけり",opts:[
 ["は",0,"説明・対比の調子。「ほかの鳥はともかく白鷺は」と理屈が立ってしまう。"],
 ["が",2,"いま目の前を渡った瞬間。動きがいちばんはっきり見える。"],
 ["の",2,"文語の主語の「の」。しらべがやわらかく、景が静かに流れていく。"],
 ["も",1,"ほかの鳥も渡っていく中で白鷺もまた。夕暮れの広がりが出るが、焦点は少しぼやける。"]]},
{pre:"凧ひとつ空のはたて",post:"残りけり",opts:[
 ["に",2,"空の果てにぽつんと止まっている。「残る」と組み合って、静かな景になる。"],
 ["へ",0,"方向の「へ」は動きを含むので「残る」とかみ合わない。「昇りけり」「消えにけり」なら合う。"],
 ["を",0,"「を」は動作の対象。「はたてを残る」は日本語として不自然。"],
 ["で",0,"「はたてで残る」は場所の説明になり、散文っぽくなる。"]]},
{pre:"月光",post:"ピアノの蓋に溜まりけり",opts:[
 ["の",2,"「月光の」で文語の主語。光が音もなくたまっていく静けさが出る。"],
 ["が",1,"主語がはっきりして、光の動きが強調される。少し硬い印象。"],
 ["は",0,"「ほかはともかく月光は」という説明調に。景より理屈が前に出る。"],
 ["も",1,"ピアノだけでなく部屋中の物に月光が、という広がり。主役がぼやける面も。"]]}
];
function joshiHTML(){
return `
<div class="card">
  <h2>助詞の使い方</h2>
  <p class="muted" style="margin-top:0">俳句の添削では、助詞を一字替えただけで句がガラッと良くなる場面がよくあります。十七音しかないので、助詞一字の重みが散文とはまるで違います。</p>
  <div class="dj-tbl-wrap"><table class="dj-tbl">
    <tr><th>助詞</th><th>主なはたらき</th><th class="hide-s">俳句での効き方</th><th>注意</th></tr>
    ${JOSHI_ROWS.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td class="hide-s">${r[2]}</td><td>${r[3]}</td></tr>`).join("")}
  </table></div>
</div>

<div class="card">
  <h2>入れ替えラボ</h2>
  <p class="muted" style="margin-top:0">空欄に助詞を入れて、景がどう変わるか比べてみましょう。<span class="dj-mark m2">◎</span>しっくり <span class="dj-mark m1">○</span>あり <span class="dj-mark m0">△</span>合わない</p>
  ${LAB.map((f,i)=>`
  <div style="margin:14px 0 18px">
    <div class="dj-frame">${f.pre}<span class="dj-slot" id="djSlot${i}">＿</span>${f.post}</div>
    <div class="seg" style="margin:6px 0">${f.opts.map((o,j)=>`<button data-lab="${i}" data-o="${j}">${o[0]}</button>`).join("")}</div>
    <div class="dj-res" id="djRes${i}"><span class="muted">助詞を選んでください</span></div>
  </div>`).join("")}
</div>

<div class="card">
  <h2>助詞ごとの解説</h2>
  <p class="muted" style="margin-top:0">例句はこのページ用に作ったものです。</p>

  <details open>
    <summary>「は」「が」「の」― 主語につく三つ</summary>
    <div class="ex">白鷺は川の向こうへ渡りけり<small>「は」：ほかの鳥と比べて「白鷺は」と説明する調子</small></div>
    <div class="ex">白鷺が川の向こうへ渡りけり<small>「が」：いま目の前を渡った、という発見と動き</small></div>
    <div class="ex">白鷺の川の向こうへ渡りけり<small>「の」：文語の主語。やわらかく、しらべがなめらか</small></div>
    <ul class="tight">
      <li><b>「は」はまず疑う</b>。「春の夜は」「母は」のように「は」を使うと、ほかとの比較や説明になりやすい。</li>
      <li><b>「が」は強い</b>。出来事がくっきり動き出すぶん、ごつごつした響きになることも。</li>
      <li><b>「の」は文語で主語にもなる</b>（「雲の行く」＝雲が行く）。しらべを柔らかくしたいときに。</li>
      <li>迷ったら三つ並べて<b>声に出して</b>読み比べる。</li>
    </ul>
  </details>

  <details>
    <summary>「の」の重ね方 ― ズームと間延び</summary>
    <ul class="tight">
      <li>「駅の／ベンチの／手袋」のように<b>大きい物から小さい物へ</b>「の」でつなぐと、カメラが寄っていく効果がある。</li>
      <li>ただし<b>三つ以上</b>続くとダラッとして、どこを見ればいいか分からなくなる。</li>
    </ul>
    <div class="ex"><span class="bad">冬日向祖母の手の甲の皺の数</span><small>「の」が四つ、中七も八音</small></div>
    <div class="ex">冬日向祖母の手の皺かぞへけり<small>「の」を二つに。「数」を動作「かぞへる」に変えて、見ている自分も入れた</small></div>
  </details>

  <details>
    <summary>「を」は動詞を呼ぶ</summary>
    <ul class="tight">
      <li>「〜を」と書くと、次に必ず動詞が要る。<b>動詞が増える原因</b>になりやすい。</li>
      <li>俳句では目的語の「を」は<b>省いても通じる</b>ことが多く、省くと引き締まる（「蜜柑をむく」→「蜜柑むく」）。</li>
      <li>ただし省いて意味が取れなくなるなら残す。</li>
    </ul>
    <div class="ex"><span class="bad">蜜柑をむく指の先から黄に染まる</span><small>上五が六音</small></div>
    <div class="ex">蜜柑むく指の先から黄に染まる<small>「を」を省いて五音に。リズムも締まる</small></div>
  </details>

  <details>
    <summary>「に」と「へ」― 止まっているか、動いているか</summary>
    <div class="ex">凧ひとつ空のはたてに残りけり<small>「に」＋「残る」：そこに止まっている静かな景</small></div>
    <div class="ex">凧ひとつ空のはたてへ昇りけり<small>「へ」＋「昇る」：まだ上がっていく途中の動き</small></div>
    <ul class="tight">
      <li>「に」は<b>行き着いた先</b>、「へ」は<b>向かう方向</b>。</li>
      <li>動詞と組み合わせを合わせる。「へ」なのに「止まる」、では景がちぐはぐになる。</li>
    </ul>
  </details>

  <details>
    <summary>「と」「で」は説明になりやすい</summary>
    <ul class="tight">
      <li><b>引用の「と」</b>（〜と思う、〜と言う）は気持ちの説明そのもの。思ったことはモノに託す。</li>
      <li><b>並べる「と」</b>（AとBと）は焦点が二つに割れる。一つに絞る。</li>
      <li><b>場所の「で」</b>（公園で、電車で）は作文の書き出しのよう。場所は、そこにあるモノで見せる。</li>
    </ul>
    <div class="ex"><span class="bad">冬の夜しずかだなあと思いけり</span><small>「〜と思う」で気持ちを説明</small></div>
    <div class="ex">冬の夜柱時計の音太し<small>静けさを、時計の音の大きさで感じさせる</small></div>
    <div class="ex"><span class="bad">公園で一人ぶらんこ漕ぎにけり</span><small>「公園で」は場所の説明</small></div>
    <div class="ex">ぶらんこの鎖の錆を握りけり<small>手ざわりから、古い公園の景が立ち上がる</small></div>
  </details>

  <details>
    <summary>「も」の効きめ</summary>
    <ul class="tight">
      <li>「〜も」は<b>ほかにもある</b>ことをにおわせて、句の外へ景を広げる。</li>
      <li>「今日も」「また」は毎日の繰り返し＝惰性になりやすい。</li>
      <li>「AもBも」と重ねると焦点が散る。</li>
    </ul>
    <div class="ex">初雪や郵便受けも少し白<small>「も」一字で、屋根も道も白くなっている町まで想像させる</small></div>
  </details>

  <details>
    <summary>「より」と「から」</summary>
    <ul class="tight">
      <li>どちらも起点。「より」は文語で引き締まり、「から」は口語で柔らかい。</li>
      <li>「から」は「〜だから」の理由にも読めるので、説明っぽくなることがある。</li>
      <li>文語の句（〜けり、〜たる）に「から」を混ぜると、文語と口語がちぐはぐに。</li>
    </ul>
    <div class="ex"><span class="bad">蝉時雨白き雲から生まれけり</span><small>口語の「から」と文語の「けり」が混ざる</small></div>
    <div class="ex">蝉時雨白き雲より生まれけり<small>「より」で文語にそろえる</small></div>
  </details>

  <details>
    <summary>切れ字「や」「かな」「けり」</summary>
    <ul class="tight">
      <li><b>や</b>：上五の終わりに置くのが基本。そこで大きく切れて、季語が舞台になる（「秋風や」）。</li>
      <li><b>かな</b>：下五の終わりで、句全体を包むように詠嘆する。</li>
      <li><b>けり</b>：「〜なのだなあ」と、いま気づいた感動。文法では助動詞だが切れ字として使う。</li>
      <li><b>「や」と「かな」は一緒に使わない</b>。感動の中心が二つになる。</li>
    </ul>
  </details>

  <details>
    <summary>助詞で音数を整える</summary>
    <ul class="tight">
      <li>中八になったら、まず<b>助詞を一つ削れないか</b>見る（「コンビニの前の」→「コンビニ前の」）。</li>
      <li>四音の季語に「や」「の」を足すと五音になる（「春雨や」「冬の夜の」）。</li>
      <li>削ったり足したりした後は、意味が変わっていないか声に出して確認。</li>
    </ul>
  </details>

  <details>
    <summary>推敲の手順</summary>
    <ol class="tight">
      <li>句の中の助詞に全部しるしをつける。</li>
      <li>一つずつ、ほかの助詞に替えて声に出して読む。</li>
      <li>景がどう変わるか（止まる／動く、説明／発見、硬い／柔らかい）を比べる。</li>
      <li>省けるもの（主に「を」「が」）は省いてみる。</li>
      <li>文語と口語がそろっているか確かめる。</li>
    </ol>
  </details>
</div>`;}

/* ================= テクニック帖 ================= */
let stars=new Set(LS.get("techo.techStars",[]));let cat="すべて",onlyStar=false;
function techShell(){return `
<div class="card">
  <h2>テクニック帖</h2>
  <p class="muted" style="margin-top:0">『プレバト!!』の俳句添削でくり返し出てくるポイントを30項目に整理しました。☆を付けると「自分の弱点」として残せます。例句はすべてこのアプリ用に作ったもので、番組の放送句ではありません。</p>
  <input type="text" id="djQ" placeholder="キーワードで探す（例：季重なり、比喩、語順）">
  <div class="seg" id="djCats"></div>
</div>
<div class="dj-cards" id="djCards"></div>`}
function renderCats(){const cs=["すべて",...new Set(T.map(x=>x.c))];
  q("#djCats").innerHTML=cs.map(c=>`<button class="${c===cat?"on":""}" data-c="${c}">${c}</button>`).join("")+`<button class="${onlyStar?"on":""}" data-star="1">☆だけ</button>`}
function renderCards(){
  const k=q("#djQ").value.trim();
  const list=T.map((x,i)=>({...x,i})).filter(x=>(cat==="すべて"||x.c===cat)&&(!onlyStar||stars.has(x.i))&&(!k||(x.t+x.p+x.b+x.a+x.w+x.c).includes(k)));
  q("#djCards").innerHTML=list.length?list.map(x=>`
  <div class="card" id="djT${x.i}">
    <button class="dj-star ${stars.has(x.i)?"on":""}" data-s="${x.i}" title="弱点として☆">${stars.has(x.i)?"★":"☆"}</button>
    <div class="dj-no">其の${x.i+1}<span class="dj-cat">${x.c}</span></div>
    <h2 style="margin:4px 0 6px;padding-right:28px">${x.t}</h2>
    <p style="margin:0 0 8px;font-size:14px">${x.p}</p>
    <div class="dj-lbl">直す前</div><div class="ex"><span class="bad">${x.b}</span></div>
    <div class="dj-lbl">添削例</div><div class="ex dj-after">${x.a}</div>
    <div class="dj-why">${x.w}</div>
    <div class="dj-chk">✓ ${x.k}</div>
  </div>`).join(""):`<p class="muted">該当するテクニックがありません。</p>`;
}
function jump(i){cat="すべて";onlyStar=false;q("#djQ").value="";renderCats();renderCards();
  if(location.hash!=="#tech")location.hash="tech";
  setTimeout(()=>{const el=document.getElementById("djT"+i);if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.classList.add("dj-flash");setTimeout(()=>el.classList.remove("dj-flash"),1600)}},120)}

/* ================= ドリル ================= */
let order=[],pos=0,score=LS.get("techo.drillScore",{ok:0,all:0});
function drillHTML(){return `
<div class="card">
  <h2>添削ドリル</h2>
  <p class="muted" style="margin-top:0">赤ペンを持つのはあなた。直す前の句を見て、自分ならどう直すか書いてから答え合わせ。</p>
  <div class="muted" id="djScore"></div>
  <div class="dj-lbl" style="margin-top:10px">直す前</div>
  <div class="dj-q" id="djDQ"></div>
  <textarea id="djDA" placeholder="あなたの添削を書いてみよう" style="font-family:'Noto Serif JP',serif"></textarea>
  <div class="row" style="margin-top:10px">
    <button class="btn" id="djHintB">ヒント</button>
    <button class="btn pri" id="djShow">答え合わせ</button>
    <button class="btn" id="djNext" style="margin-left:auto">次の句 →</button>
  </div>
  <p class="dj-hint" id="djHint"></p>
  <div class="dj-rev" id="djRev">
    <div class="dj-lbl">添削例</div>
    <div class="ex dj-after" id="djAfter" style="font-size:20px"></div>
    <div class="dj-why" id="djWhy"></div>
    <p style="font-size:13px;margin:6px 0">関連テクニック：<a href="#tech" id="djLink" style="color:var(--shu)"></a></p>
    <div class="row"><button class="btn sm" data-self="1">できた！</button><button class="btn sm" data-self="0">まだまだ</button></div>
  </div>
</div>`}
function shuffle(){order=T.map((_,i)=>i).sort(()=>Math.random()-.5);pos=0}
function drill(){const x=T[order[pos]];
  q("#djDQ").textContent=x.b;q("#djDA").value="";q("#djRev").classList.remove("on");q("#djHint").classList.remove("on");
  q("#djHint").textContent="ヒント："+x.k;q("#djAfter").textContent=x.a;q("#djWhy").textContent=x.w;
  q("#djLink").textContent="其の"+(order[pos]+1)+"「"+x.t+"」";
  q("#djScore").textContent=`第${pos+1}問／全${T.length}問　自己採点：${score.ok}／${score.all} できた`}
function nextQ(){pos++;if(pos>=order.length)shuffle();drill()}

